const group = document.querySelector('[data-testid="colour-swatch-group"]');
const swatches = Array.from(document.querySelectorAll('[data-testid="colour-swatch"]'));
const label = group.querySelector('span');
const buttons = Array.from(group.querySelectorAll('button'));

const swatchInfo = swatches.map((s, i) => {
  const cs = getComputedStyle(s);
  return {
    i,
    tag: s.tagName,
    role: s.getAttribute('role'),
    ariaChecked: s.getAttribute('aria-checked'),
    tabIndex: s.tabIndex,
    borderBottomWidth: cs.borderBottomWidth,
    borderBottomColor: cs.borderBottomColor,
    borderBottomStyle: cs.borderBottomStyle,
    borderTopWidth: cs.borderTopWidth,
    borderLeftWidth: cs.borderLeftWidth,
    borderRightWidth: cs.borderRightWidth,
    width: cs.width,
    height: cs.height,
    backgroundColor: cs.backgroundColor,
  };
});

const buttonInfo = buttons.map((b) => {
  const cs = getComputedStyle(b);
  return {
    ariaLabel: b.getAttribute('aria-label'),
    disabled: b.disabled,
    color: cs.color,
    cursor: cs.cursor,
  };
});

JSON.stringify({ swatchCount: swatches.length, swatchInfo, buttonInfo, labelText: group.textContent }, null, 2);

const swatches = Array.from(document.querySelectorAll('[data-testid="colour-swatch"]'));
const focusable = swatches.find(s => s.tabIndex === 0);
focusable.focus();
const cs = getComputedStyle(focusable);
JSON.stringify({
  activeElementIsFocusable: document.activeElement === focusable,
  outline: cs.outline,
  outlineWidth: cs.outlineWidth,
  outlineColor: cs.outlineColor,
  outlineStyle: cs.outlineStyle,
  outlineOffset: cs.outlineOffset,
  position: cs.position,
  zIndex: cs.zIndex,
}, null, 2);

const el = document.activeElement;
const cs = getComputedStyle(el);
JSON.stringify({
  activeTag: el.tagName,
  ariaLabel: el.getAttribute('aria-label'),
  dataTestId: el.getAttribute('data-testid'),
  outline: cs.outline,
  outlineWidth: cs.outlineWidth,
  outlineColor: cs.outlineColor,
  outlineStyle: cs.outlineStyle,
  outlineOffset: cs.outlineOffset,
  position: cs.position,
  zIndex: cs.zIndex,
  matchesFocusVisible: el.matches(':focus-visible'),
}, null, 2);

const group = document.querySelector('[data-testid="colour-swatch-group"]');
JSON.stringify({
  text: group.textContent,
  swatchCount: document.querySelectorAll('[data-testid="colour-swatch"]').length,
  radiogroupExists: !!document.querySelector('[role="radiogroup"]'),
}, null, 2);

const iframe = document.getElementById('storybook-preview-iframe');
const doc = iframe.contentDocument;
const group = doc.querySelector('[data-testid="colour-swatch-group"]');
JSON.stringify({
  found: !!group,
  text: group?.textContent,
  swatchCount: doc.querySelectorAll('[data-testid="colour-swatch"]').length,
  radiogroupExists: !!doc.querySelector('[role="radiogroup"]'),
}, null, 2);

